import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'ai-engineer-production-infra-l4-001', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'GPU Optimization', question: 'What is the difference between the prefill and decode phases of LLM inference from a GPU utilization perspective?', options: ['Prefill is always the bottleneck in LLM inference', 'Prefill processes many tokens in parallel (compute-bound, high GPU utilization ~70-90%). Decode generates one token at a time, loading all model weights for minimal computation (memory-bandwidth-bound, low GPU utilization ~10-30%). This means decode is the bottleneck for autoregressive generation — the GPU is mostly waiting for data from HBM rather than computing. Optimizations like quantization, speculative decoding, and KV cache optimization primarily target the decode phase', 'GPU utilization is constant throughout inference', 'Both phases have identical GPU utilization'], correctAnswer: 1, explanation: 'Arithmetic intensity: Prefill with N tokens: each layer does O(N²·d) compute with O(N·d²) memory reads → AI ∝ N (increases with prompt length). For N=1000, d=4096: AI ≈ 244 ops/byte — compute-bound on H100 (990 TFLOPS / 3.35 TB/s = 295 ops/byte). Decode with 1 token: each layer does O(d²) compute with O(d²) memory reads → AI ≈ 1 op/byte — severely memory-bound. Solutions: (a) increase decode batch size (AI ∝ batch_size), (b) quantization reduces memory reads (INT4 = 2x less data), (c) speculative decoding generates multiple tokens per decode step, (d) continuous batching keeps the GPU fed with multiple concurrent requests.', tags: ['prefill', 'decode', 'gpu-utilization', 'memory-bound'] },
  { id: 'ai-engineer-production-infra-l4-002', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Model Serving', question: 'What is TensorRT-LLM and how does it optimize LLM inference on NVIDIA GPUs?', options: ['TensorRT-LLM compiles LLM models into optimized TensorRT engines with: (1) kernel fusion (combine multiple operations into single GPU kernels), (2) FP8/INT4 quantization with calibration, (3) in-flight batching (continuous batching of requests), (4) KV cache management with paged attention, (5) tensor parallelism across multiple GPUs, (6) custom CUDA kernels for attention and MLP operations. This achieves 2-4x higher throughput compared to standard PyTorch inference on the same hardware', 'TensorRT-LLM is a training framework', 'TensorRT-LLM only supports NVIDIA T4 GPUs', 'TensorRT-LLM provides no speedup over PyTorch'], correctAnswer: 0, explanation: 'TensorRT-LLM optimization pipeline: (1) Convert model from PyTorch/HuggingFace format to TRT-LLM format, (2) Apply graph optimizations (layer fusion: QKV projection → single GEMM, layernorm + activation fusion), (3) Quantize to FP8/INT4 with calibration dataset, (4) Compile to TensorRT engine (optimized CUDA kernels per GPU architecture), (5) Deploy with Triton Inference Server or TRT-LLM runtime with continuous batching. Performance: LLaMA-70B on 4×H100: ~2000 output tokens/sec (TRT-LLM) vs ~600 tokens/sec (vLLM with PyTorch), ~3.3x speedup. Trade-off: longer build time (minutes to hours for compilation), less flexibility (model changes require recompilation). Best for: production serving where throughput matters and model is stable.', tags: ['tensorrt-llm', 'nvidia', 'kernel-fusion', 'optimization'] },
  { id: 'ai-engineer-production-infra-l4-003', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Autoscaling', question: 'How should GPU-based ML inference services be autoscaled?', options: ['Standard CPU-based autoscaling rules apply to GPU services', 'GPU autoscaling should use the same metrics as CPU autoscaling', 'GPU autoscaling challenges: (1) GPU instances take 5-10 minutes to start (model loading time), requiring proactive scaling, (2) GPU memory utilization is a better scaling signal than CPU/GPU compute utilization for LLMs (KV cache fills before compute saturates), (3) request queue depth is a more responsive signal than utilization. Best practice: scale on request queue length with predictive scaling (use historical traffic patterns to pre-scale before known peaks), warm standby instances for rapid scale-up, and scale-to-zero with cold start tolerance for low-traffic periods', 'GPU instances can be started instantly like CPU instances'], correctAnswer: 2, explanation: 'GPU autoscaling strategy: (1) Primary metric: request queue depth > threshold for > 30 seconds → scale up. (2) Predictive: historical traffic patterns (e.g., 2x traffic during business hours) → pre-scale 15 minutes before expected peak. (3) Scale-up speed: maintain warm pool of 1-2 instances with models loaded (costly but enables fast scaling). (4) Scale-down: conservative (wait 10+ minutes of low utilization before removing GPU instance, since restarting is expensive). (5) Custom metrics: KV cache utilization (for LLMs), batch queue occupancy, rejection rate. KServe on Kubernetes: supports scale-to-zero (Knative serverless) for rarely-used models — cold start takes 2-5 minutes (model loading). Acceptable for internal tools, not for user-facing real-time. For user-facing: always maintain minimum replicas with loaded models.', tags: ['autoscaling', 'gpu', 'queue-depth', 'predictive-scaling'] },
  { id: 'ai-engineer-production-infra-l4-004', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Networking', question: 'Why is GPU-to-GPU interconnect bandwidth critical for distributed LLM inference?', options: ['Tensor parallelism requires no communication between GPUs', 'Distributed LLM inference (tensor parallelism) requires all-reduce operations between GPUs at every transformer layer — twice per layer (after attention and after FFN). The interconnect bandwidth determines the communication overhead: NVLink (900 GB/s) enables efficient tensor parallelism within a node, while Ethernet/InfiniBand connects nodes. For a 70B model split across 4 GPUs: each all-reduce transfers ~hidden_size×batch×2 bytes per layer. Slow interconnect turns communication into the bottleneck, negating parallelism benefits', 'All GPUs communicate at the same speed regardless of interconnect', 'Interconnect bandwidth only matters for training, not inference'], correctAnswer: 1, explanation: 'Tensor parallel communication: for each transformer layer, 2 all-reduce operations (attention + FFN). All-reduce volume: 2 × batch_size × seq_len × hidden_dim × dtype_bytes per operation. For hidden=8192, batch=16, seq=1 (decode), FP16: 2 × 16 × 1 × 8192 × 2 = 524KB per all-reduce, 4 per layer, 80 layers = 167MB total per decode step. NVLink (900 GB/s intra-node): 167MB / 900 GB/s = 0.19ms — negligible. Ethernet (100 Gbps = 12.5 GB/s inter-node): 167MB / 12.5 GB/s = 13ms — significant compared to ~25ms compute per decode step. This is why: (1) tensor parallelism works well within a node (NVLink), (2) pipeline parallelism (less communication) is preferred across nodes, (3) H100 SXM with NVSwitch (900 GB/s all-to-all) is ideal for TP-8 inference of large models.', tags: ['interconnect', 'nvlink', 'tensor-parallelism', 'bandwidth'] },
  { id: 'ai-engineer-production-infra-l4-005', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Cost', question: 'How should GPU instance types be selected for different ML workloads?', options: ['GPU memory is irrelevant for inference workloads', 'All ML workloads should use the same GPU type', 'GPU selection depends on workload characteristics: (1) Training large models: H100 SXM (highest compute + NVLink for multi-GPU), (2) Fine-tuning: A100 40/80GB (good compute, sufficient memory for most models), (3) Inference of large LLMs: H100/A100 (need high memory bandwidth for decode), (4) Inference of smaller models: A10G or L4 (lower cost, sufficient for <13B models), (5) Batch embedding: A10G (good throughput/cost ratio for matrix operations). Cost per token can differ 5-10x between GPU types, so matching workload to hardware is critical for cost efficiency', 'The most expensive GPU is always the best choice'], correctAnswer: 2, explanation: 'GPU comparison for inference (approximate, 2024 pricing): H100 SXM: $4/hr, 80GB HBM3 (3.35 TB/s), best for 70B+ models. A100 80GB: $3/hr, 80GB HBM2e (2 TB/s), good for 13-70B models. A10G: $1/hr, 24GB GDDR6 (600 GB/s), good for <13B models. L4: $0.70/hr, 24GB GDDR6 (300 GB/s), good for small models + batch. T4: $0.35/hr, 16GB GDDR6 (320 GB/s), budget option. Example: serving LLaMA-3-8B (INT4): fits on A10G (24GB) or L4 (24GB). A10G throughput: ~30 tok/s. H100: ~120 tok/s. Cost per 1M tokens: A10G $0.009, H100 $0.009. Same cost per token but H100 handles 4x more concurrent requests → better for high-traffic. For low-traffic: A10G is more cost-effective (don\'t pay for unused H100 capacity).', tags: ['gpu-selection', 'cost-optimization', 'h100', 'a10g'] },
  { id: 'ai-engineer-production-infra-l4-006', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Containerization', question: 'What are the best practices for containerizing ML models with GPU support?', options: ['Model weights should always be baked into the container image', 'GPU container best practices: (1) use NVIDIA base images (nvidia/cuda or nvcr.io) with matching CUDA version, (2) install nvidia-container-toolkit on the host, (3) multi-stage builds: large build stage (compilers, dev libs) → small runtime stage (only runtime libs + model), (4) separate model weights from container image (mount from persistent storage or download at startup), (5) pin all dependency versions for reproducibility, (6) use health checks that verify GPU access and model loading. Container size optimization: 15GB base → 5GB with multi-stage + distroless runtime', 'Standard Docker containers automatically support GPUs', 'Docker containers cannot access GPUs'], correctAnswer: 1, explanation: 'Dockerfile pattern: Stage 1 (build): FROM nvidia/cuda:12.1-devel → install compilers + build dependencies → compile custom CUDA kernels. Stage 2 (runtime): FROM nvidia/cuda:12.1-runtime → copy compiled binaries from stage 1 → install only runtime dependencies (torch, vllm). Model weights: mount from S3/GCS at startup (not baked in, because model updates shouldn\'t require container rebuild). GPU detection: HEALTHCHECK that runs nvidia-smi and validates model is loaded on GPU. Container size: full dev image ~15GB, runtime-only ~5GB, with model downloaded separately (~14GB for 7B FP16). Kubernetes: use NVIDIA device plugin for GPU scheduling, set resource limits (nvidia.com/gpu: 1), and tolerate GPU node taints. Important: CUDA version in container must be ≤ driver version on host (forward compatible within major version).', tags: ['docker', 'gpu-containers', 'multi-stage-build', 'nvidia-container-toolkit'] },
  { id: 'ai-engineer-production-infra-l4-007', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Edge Deployment', question: 'What are the key optimization techniques for deploying ML models on edge devices?', options: ['Edge devices can run the same models as cloud GPUs', 'Cloud models can be deployed to edge without any modifications', 'Edge devices have unlimited compute and memory', 'Edge optimization techniques: (1) quantization (INT8/INT4 reduces model size and speeds inference on edge NPUs), (2) pruning (remove unnecessary weights for smaller model), (3) knowledge distillation (train small edge model to mimic large cloud model), (4) model architecture search for edge (MobileNet, EfficientNet designed for edge), (5) framework optimization (TFLite, CoreML, ONNX Runtime Mobile compile models for specific hardware), (6) operator fusion (combine layers into single operations reducing memory transfers). Target: <50ms inference, <100MB model, <1W power'], correctAnswer: 3, explanation: 'Edge deployment pipeline: (1) Start with cloud model (e.g., ResNet-50, 98MB FP32), (2) Knowledge distillation to MobileNetV3 (22MB FP32, 1% accuracy loss), (3) Quantization to INT8 (5.5MB, <0.5% additional accuracy loss), (4) Convert to target runtime (TFLite for Android, CoreML for iOS, ONNX for cross-platform), (5) Operator fusion and optimization by the runtime. Performance: MobileNetV3-INT8 on Pixel 6 NPU: 3ms inference, 5.5MB model. For LLMs on edge: Gemma-2B quantized to INT4 runs on mobile at ~10 tokens/second (llama.cpp with Metal/NNAPI acceleration). MLC-LLM provides optimized LLM inference for mobile. Key constraint: memory (typical phone has 6-12GB RAM shared with OS and apps, so model must be <2-4GB).', tags: ['edge-deployment', 'quantization', 'tflite', 'mobile-inference'] },
  { id: 'ai-engineer-production-infra-l4-008', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Serving Framework', question: 'What are the key differences between vLLM, TGI (Text Generation Inference), and SGLang for LLM serving?', options: ['Only vLLM supports continuous batching', 'All LLM serving frameworks are identical', 'vLLM: PagedAttention for memory-efficient KV cache management, continuous batching, and broad model support. Best for general-purpose LLM serving. TGI (Hugging Face): production-ready with built-in monitoring, token streaming, and HuggingFace Hub integration. Best for HuggingFace ecosystem. SGLang: RadixAttention for efficient prefix caching, constrained decoding, and a programming interface for complex LLM programs. Best for multi-turn and structured generation workloads. Each optimizes different aspects of the serving stack', 'TGI is the only framework that supports streaming'], correctAnswer: 2, explanation: 'vLLM: PagedAttention (virtual memory for KV cache, near-zero fragmentation), supports 100+ model architectures, OpenAI-compatible API, prefix caching, multi-LoRA serving. TGI: Rust-based router + Python model server, flash attention, speculative decoding, watermarking, Prometheus metrics built-in, tight HuggingFace integration. SGLang: RadixAttention (tree-based prefix caching more efficient than vLLM\'s for shared prefixes), constrained decoding via FSM, frontend DSL for complex LLM programs (branching, loops). Performance comparison (LLaMA-70B, H100×4): throughput is similar (within 20%), differences emerge in specific workloads — SGLang wins on multi-turn with shared system prompts (RadixAttention), vLLM wins on diverse independent requests (PagedAttention), TGI wins on ease of deployment with monitoring.', tags: ['vllm', 'tgi', 'sglang', 'serving-comparison'] },
  { id: 'ai-engineer-production-infra-l4-009', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Batch Processing', question: 'How should large-scale batch inference jobs be designed for cost efficiency?', options: ['Cost-efficient batch inference: (1) use spot/preemptible instances (60-90% cheaper) with checkpointing for fault tolerance, (2) maximize batch size to saturate GPU compute, (3) sort inputs by length to minimize padding waste, (4) use data-parallel processing across many GPUs, (5) pipeline data loading and inference, (6) write results to durable storage (S3) with exactly-once semantics via idempotent writes. Batch inference achieves 5-20x better cost per prediction than real-time serving by maximizing GPU utilization and using cheaper instances', 'Batch inference should use the same infrastructure as real-time serving', 'Spot instances are too unreliable for any ML workload', 'Batch inference has the same cost per prediction as real-time'], correctAnswer: 0, explanation: 'Batch architecture: Job scheduler (Airflow/K8s Job) → Worker pool (spot GPU instances) → Each worker: read batch from queue → inference → write results to S3. Checkpointing: save progress every 1000 items. If spot instance is reclaimed: restart from checkpoint (lose at most 1000 items of compute, ~30 seconds). Length sorting: padding 10-token inputs to match 1000-token inputs wastes 99% of compute. Sort by length, batch similar lengths together → 3-5x throughput improvement. Cost comparison: 1M embedding requests. Real-time (4×A10G always-on): $96/day, serves 1M in ~2 hours. Batch (4×A10G spot, $0.30/hr each): 4×$0.30×2h = $2.40. 40x cheaper. For LLMs: OpenAI batch API offers 50% cost reduction + higher rate limits. Self-hosted: vLLM offline mode maximizes throughput by processing all prompts with optimal batching.', tags: ['batch-inference', 'spot-instances', 'checkpointing', 'cost-efficiency'] },
  { id: 'ai-engineer-production-infra-l4-010', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Monitoring', question: 'What GPU-specific metrics should be monitored for ML inference services?', options: ['Standard CPU metrics are sufficient for GPU monitoring', 'GPU memory usage is always constant during inference', 'GPU-specific metrics: (1) GPU utilization % (compute activity), (2) GPU memory utilization (used vs total HBM), (3) GPU memory bandwidth utilization (data transfer rate), (4) SM (streaming multiprocessor) occupancy, (5) GPU temperature (thermal throttling above 83°C), (6) PCIe throughput (host-device transfer), (7) NVLink throughput (GPU-GPU transfer for multi-GPU), (8) power consumption. For LLM serving: also monitor KV cache utilization, batch size distribution, tokens per second per GPU, and TTFT. nvidia-smi, DCGM, and Prometheus exporters provide these metrics', 'GPU temperature monitoring is unnecessary'], correctAnswer: 2, explanation: 'Critical monitoring setup: (1) DCGM (Data Center GPU Manager) exports metrics to Prometheus. Key alerts: GPU utilization < 20% for >5 min (underutilized, wasting money), GPU memory > 95% (risk of OOM), GPU temp > 80°C (approaching thermal throttle). (2) Application-level: tokens/second (throughput), p99 TTFT (user experience), batch size (GPU utilization proxy), KV cache occupancy (memory management health), request queue depth (scaling signal). Dashboard layout: top row = business metrics (requests/sec, error rate), middle = model metrics (tokens/sec, batch size), bottom = GPU metrics (utilization, memory, temp). Correlation: if tokens/sec drops while GPU utilization is high and memory is full → KV cache is full, need more GPUs or shorter max context. If tokens/sec drops and GPU utilization is low → upstream issue (no requests reaching GPU).', tags: ['gpu-monitoring', 'dcgm', 'metrics', 'thermal-throttling'] },
  { id: 'ai-engineer-production-infra-l4-011', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Model Loading', question: 'How can model loading time be reduced for faster service startup and scaling?', options: ['Model loading optimizations: (1) SafeTensors format (memory-mapped loading, 2-10x faster than pickle), (2) tensor parallelism-aware sharding (pre-shard model so each GPU loads only its partition), (3) S3/GCS with high-bandwidth network (100 Gbps → 14GB model in ~1 second), (4) local NVMe cache (pre-download models to local SSD), (5) warm pool (keep standby instances with models already loaded), (6) shared memory for multiple model replicas on the same node. These reduce cold start from 5-10 minutes to 30-60 seconds for large models', 'Model loading time cannot be optimized', 'Model loading is instantaneous on modern hardware', 'All model formats load at the same speed'], correctAnswer: 0, explanation: 'Loading time breakdown for a 70B model (140GB FP16): (1) Download from S3 (25 Gbps): 45 seconds, (2) Deserialize (pickle): 60-120 seconds. SafeTensors: mmap, ~0 seconds (pages loaded on demand). (3) Transfer to GPU: 140GB / 64 GB/s (PCIe 5.0): ~2 seconds per GPU, but 4 GPUs in parallel. (4) torch.compile warmup (optional): 30-120 seconds. Total with pickle: 2-3 minutes. Total with SafeTensors + pre-sharded + local NVMe: 30-45 seconds. Further optimization: (a) model already on NVMe (skip download), (b) pre-sharded for tensor parallelism (each GPU file is 35GB, loads independently), (c) skip torch.compile for initial requests, compile in background. For autoscaling: warm pool of 1-2 instances with models loaded provides near-instant scaling. Cost: $8-12/hr for warm standby H100 instances.', tags: ['model-loading', 'safetensors', 'cold-start', 'warm-pool'] },
  { id: 'ai-engineer-production-infra-l4-012', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Multi-GPU', question: 'What are the trade-offs between tensor parallelism and pipeline parallelism for multi-GPU LLM inference?', options: ['Tensor parallelism requires no inter-GPU communication', 'Pipeline parallelism always has lower latency than tensor parallelism', 'Tensor parallelism (TP): splits each layer across GPUs, requiring 2 all-reduce operations per layer (high bandwidth needed, but low latency — all GPUs work simultaneously). Pipeline parallelism (PP): assigns different layers to different GPUs, requiring only one point-to-point transfer per micro-batch between GPUs (low bandwidth, but introduces pipeline bubbles). TP is preferred within a node (NVLink), PP across nodes (slower interconnect). For serving: TP reduces per-request latency, PP increases throughput through micro-batching', 'Tensor and pipeline parallelism are identical'], correctAnswer: 2, explanation: 'TP example: 70B model on 4 GPUs. Each GPU has 1/4 of each layer\'s weights. At each layer: all-reduce to synchronize. Latency = compute/4 + comm. With NVLink (900 GB/s): comm ≈ 0.2ms per layer, minimal impact. PP example: 70B model on 4 GPUs. GPU 1 has layers 1-20, GPU 2 has 21-40, etc. Request flows through GPUs sequentially. Latency = full compute (no parallelism per request!). But: with micro-batching, GPU 1 works on batch 2 while GPU 2 works on batch 1 → higher throughput. Best practice: TP within a node (NVLink), PP across nodes if needed, or TP×PP combinations. For a 70B model on 8 GPUs (2 nodes × 4 GPUs): TP=4 within each node, PP=2 across nodes. This minimizes cross-node communication (PP only sends activations once per micro-batch) while leveraging intra-node NVLink for TP.', tags: ['tensor-parallelism', 'pipeline-parallelism', 'multi-gpu', 'inference'] },
  { id: 'ai-engineer-production-infra-l4-013', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Quantization', question: 'What is the practical impact of FP8 versus INT8 versus INT4 quantization on LLM inference performance?', options: ['All quantization formats provide identical performance', 'Quantization never affects model quality', 'INT4 always has better quality than FP8', 'FP8 (H100+): 2x throughput vs FP16 with minimal quality loss (<0.5% on most benchmarks), native hardware support. INT8 (most GPUs): 2x throughput, requires careful calibration, may lose 1-2% quality. INT4 (GPTQ/AWQ): 4x memory reduction enabling larger models on fewer GPUs, but 2-5% quality loss and requires specialized kernels. The practical impact depends on whether inference is compute-bound (FP8/INT8 help) or memory-bound (INT4 helps by fitting larger batches or using fewer GPUs)'], correctAnswer: 3, explanation: 'Practical comparison for LLaMA-70B on H100: FP16: 140GB (2×H100), ~25 tok/s per request. FP8: 70GB (1×H100), ~35 tok/s (1.4x faster, H100 has FP8 tensor cores). INT8 (SmoothQuant): 70GB, ~30 tok/s (1.2x faster, INT8 GEMM). INT4 (AWQ): 35GB (1×H100 with room for KV cache), ~20 tok/s per request but can batch 2x more concurrent requests → 2x throughput. Quality (MMLU): FP16 baseline=70.0, FP8=69.8, INT8=69.5, INT4=68.5. For production: FP8 on H100 is the sweet spot (minimal quality loss, significant speedup, native support). INT4 when you need to fit the model on fewer GPUs (cost reduction) or serve very long contexts (more KV cache space). INT8 as a fallback on older GPUs without FP8 support (A100, A10G).', tags: ['fp8', 'int8', 'int4', 'quantization-comparison'] },
  { id: 'ai-engineer-production-infra-l4-014', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Security', question: 'How should model weights be secured in production environments?', options: ['Encryption makes model inference impossible', 'Model weights are public information that do not need protection', 'Model weight security: (1) encrypt weights at rest (AES-256 in cloud storage), (2) encrypt in transit (TLS between storage and GPU servers), (3) access control (IAM policies limiting who can download weights), (4) runtime protection (prevent model extraction via API — rate limiting, output perturbation), (5) model signing (verify weight integrity before loading — detect tampering), (6) secure enclaves (confidential computing with TEEs for highest security). For proprietary models, weights are the core IP — unauthorized access enables competitors to replicate or fine-tune the model', 'Model weights do not need security measures'], correctAnswer: 2, explanation: 'Security layers: (1) Storage: S3 with server-side encryption (SSE-KMS), bucket policies restricting access to specific IAM roles, versioning for integrity. (2) Network: private VPC endpoints for S3 access (no public internet), TLS 1.3 for all transfers. (3) Compute: GPU nodes in private subnet, no direct internet access, model loaded from encrypted storage. (4) API: rate limiting prevents bulk model extraction via repeated queries (model stealing attacks). (5) Integrity: SHA-256 hash of model files checked before loading — detect if weights were tampered. (6) Access audit: CloudTrail logs all model file access. For high-security (military, financial): NVIDIA Confidential Computing encrypts GPU memory, preventing even cloud provider from accessing model weights. SafeTensors format prevents arbitrary code execution during model loading (unlike pickle).', tags: ['model-security', 'encryption', 'access-control', 'confidential-computing'] },
  { id: 'ai-engineer-production-infra-l4-015', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Networking', question: 'How does request routing work for multi-model ML serving platforms?', options: ['All requests go to the same model instance', 'Request routing adds no latency to ML inference', 'Multi-model serving requires separate infrastructure per model', 'Multi-model routing: (1) API gateway receives request with model identifier, (2) route to appropriate model cluster based on: model name/version, request priority, GPU availability, (3) within a model cluster: load balance across replicas (least-connections for variable-latency inference), (4) handle model versioning: support blue-green deployment, canary traffic splitting, and A/B testing at the routing layer. For multi-LoRA: route to GPU with the appropriate LoRA adapter loaded (or swap adapters). Service mesh (Istio) or custom routing layer provides traffic management'], correctAnswer: 3, explanation: 'Multi-model serving architecture: (1) Ingress/API Gateway: TLS termination, authentication, rate limiting. (2) Model Router: maps (model_name, version) → target endpoint. Supports traffic splitting: model_v2 gets 10% of traffic (canary). (3) Model Cluster: each model has N replicas behind a load balancer. Scaling independently per model based on traffic. (4) GPU Scheduling: ModelMesh (IBM) or KServe multi-model serving packs multiple models per GPU, loading/unloading based on demand. For LLM platforms: S-LoRA serves 100+ LoRA adapters on shared base models. Router determines which adapter is needed per request. If adapter not in GPU memory: load (~100ms for small adapter) and serve. Frequently used adapters stay cached. This enables cost-efficient multi-tenant LLM platforms.', tags: ['request-routing', 'multi-model', 'service-mesh', 'load-balancing'] },
  { id: 'ai-engineer-production-infra-l4-016', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Observability', question: 'How should distributed tracing be implemented for ML inference pipelines?', options: ['ML-specific distributed tracing should capture: (1) request preprocessing (tokenization time, feature extraction), (2) queue wait time, (3) inference computation (per-layer timing for debugging), (4) post-processing (detokenization, safety filtering), (5) ML-specific metadata (model version, batch size, token counts, GPU utilization during inference). Each span should carry: request_id, model_version, input_tokens, output_tokens, and any safety filter results. This enables: root cause analysis of latency spikes, cost attribution per request, and quality debugging', 'Tracing should only capture total request latency', 'ML inference is too fast to benefit from tracing', 'Standard APM tracing is sufficient for ML pipelines'], correctAnswer: 0, explanation: 'Tracing span hierarchy for an LLM request: [API Gateway: 2ms] → [Preprocessing: 5ms (tokenization: 3ms, prompt template: 2ms)] → [Queue: 50ms] → [Inference: 2000ms (prefill: 200ms, decode: 1800ms)] → [Post-processing: 10ms (detokenize: 5ms, safety check: 5ms)]. Metadata per span: model=llama-3-70b-v2, batch_size=8, prompt_tokens=512, completion_tokens=200, gpu_util=0.75. Tools: OpenTelemetry for instrumentation, Jaeger/Tempo for trace storage/visualization. LLM-specific: LangSmith/Langfuse trace multi-step LLM chains (RAG pipeline: query → embed → retrieve → rerank → generate, each as a span). Alert on: p99 inference time > SLA, queue wait > threshold, safety filter blocking rate > baseline.', tags: ['distributed-tracing', 'opentelemetry', 'observability', 'latency-analysis'] },
  { id: 'ai-engineer-production-infra-l4-017', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Storage', question: 'What storage architecture is optimal for serving ML models at scale?', options: ['All models should be stored on local disk', 'Tiered model storage: (1) L1: GPU HBM (active model weights + KV cache — fastest, limited capacity), (2) L2: host RAM (model swap pool for multi-model serving), (3) L3: local NVMe SSD (model cache, ~5GB/s read), (4) L4: object storage (S3/GCS — persistent, unlimited, ~1GB/s per connection). Model loading path: S3 → NVMe cache → RAM → GPU. Pre-caching popular models on NVMe eliminates S3 download time. For multi-model serving: maintain a model cache in host RAM with LRU eviction, loading to GPU on demand', 'Object storage is fast enough for real-time model loading', 'Only one storage tier is needed for ML serving'], correctAnswer: 1, explanation: 'Storage performance: GPU HBM (H100): 3.35 TB/s, 80GB. Host RAM (DDR5): 200 GB/s, 256-2048GB. NVMe SSD: 5-7 GB/s, 2-8TB. S3: ~1 GB/s per connection (parallel downloads), unlimited. Model loading times for 14GB model (7B FP16): From GPU HBM: 0ms (already loaded). From RAM: 0.07s (rare — GPU-to-GPU is more common). From NVMe: 2-3s. From S3: 10-15s. Multi-model serving strategy: keep top-5 most requested models in GPU HBM, next 20 in host RAM, next 100 on NVMe, all models in S3. When a request arrives for a model not in GPU: check RAM (fast swap) → NVMe (moderate delay) → S3 (cold start). This caching hierarchy minimizes average model loading latency while supporting a large model catalog.', tags: ['storage-architecture', 'model-caching', 'nvme', 'tiered-storage'] },
  { id: 'ai-engineer-production-infra-l4-018', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Reliability', question: 'How should ML serving systems handle GPU failures gracefully?', options: ['GPU failures are too rare to plan for', 'GPU failure handling: (1) health checks: periodically run a small inference (every 30s) to verify GPU responsiveness, (2) automatic restart: if GPU is unresponsive, drain requests and restart the container (often fixes transient CUDA errors), (3) redundancy: deploy across multiple GPUs/nodes with load balancing, (4) fallback: if all GPUs fail, route to CPU inference (slower but available) or return cached predictions, (5) automatic GPU memory recovery: detect OOM conditions and restart with cleared memory. GPU failure rate in cloud: ~1-2% annually per GPU, higher under sustained load and thermal stress', 'GPU failures cannot be recovered from without manual intervention', 'ML systems do not need redundancy'], correctAnswer: 1, explanation: 'GPU failure modes: (1) CUDA OOM: KV cache grows beyond memory. Recovery: kill request, clear cache, restart. Prevention: set max_sequence_length. (2) GPU hang: NCCL timeout in multi-GPU. Recovery: restart container (kills stuck CUDA context). (3) ECC error: uncorrectable memory error. Recovery: mark GPU as unhealthy, migrate to different node. (4) Thermal throttling: performance degrades. Recovery: reduce batch size temporarily. Kubernetes handling: liveness probe fails → container restart → GPU re-initialized. Readiness probe fails → remove from load balancer → traffic routed to healthy replicas. Node-level GPU failure: Kubernetes detects unhealthy GPU via NVIDIA device plugin → marks node as NotReady → pods rescheduled to healthy nodes. SLA: with 3+ replicas across 2+ AZs, achieve 99.99% availability despite individual GPU failures.', tags: ['gpu-failure', 'reliability', 'health-checks', 'graceful-degradation'] },
  { id: 'ai-engineer-production-infra-l4-019', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Inference Optimization', question: 'What is speculative decoding and how much speedup does it provide in practice?', options: ['Speculative decoding uses a small draft model to generate k candidate tokens, then the large target model verifies all k tokens in a single forward pass. Accepted tokens skip expensive target model decode steps. It is mathematically guaranteed to produce the same output distribution as the target model (lossless). Practical speedup: 1.5-3x depending on draft model quality and acceptance rate. The speedup is greatest when the draft model closely matches the target model (high acceptance rate), e.g., a 68M draft model for a 7B target', 'Speculative decoding always provides exactly 2x speedup', 'Speculative decoding changes the output distribution', 'Speculative decoding is an approximation that degrades quality'], correctAnswer: 0, explanation: 'Speculative decoding mechanics: (1) draft model generates k=5 tokens autoregressively (cheap: ~5ms for 68M model), (2) target model processes all 5 tokens in a single forward pass (~25ms, same as processing 1 token because decode is memory-bound), (3) verify: for each position, if p_target(token) >= p_draft(token), accept. Otherwise, accept with probability p_target/p_draft and resample the rest. Expected accepted tokens: depends on agreement rate α between draft and target. If α=0.8: expected ~4 tokens per speculation step vs 1 token without. Speedup: k/(1 + k·c_draft/c_target) where c_draft/c_target is the draft/target cost ratio. Practical: 2-3x for well-matched models (Medusa heads, same-family smaller model). Meta\'s Llama 3 uses speculative decoding in production.', tags: ['speculative-decoding', 'inference-speedup', 'draft-model', 'lossless'] },
  { id: 'ai-engineer-production-infra-l4-020', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'CUDA', question: 'What is the CUDA memory hierarchy and how does it affect ML inference performance?', options: ['CUDA has a flat memory model with no hierarchy', 'All GPU memory has the same access speed', 'CUDA memory hierarchy: (1) Registers (fastest, per-thread, ~256KB per SM), (2) Shared memory/L1 cache (~164KB per SM, shared by thread block, ~100x faster than HBM), (3) L2 cache (H100: 50MB, shared by all SMs), (4) HBM (H100: 80GB, 3.35 TB/s bandwidth). Flash Attention exploits this: it tiles attention computation to fit in shared memory (SRAM), avoiding materializing the N×N attention matrix in HBM. Understanding this hierarchy is critical for writing custom CUDA kernels and choosing optimization strategies', 'ML inference does not benefit from the GPU cache hierarchy'], correctAnswer: 2, explanation: 'Access latency and bandwidth: Registers: 0 cycles, ~20 TB/s per SM. Shared memory (SRAM): ~20-30 cycles, ~19 TB/s per SM (on H100). L2 cache: ~200 cycles, ~12 TB/s. HBM: ~400 cycles, 3.35 TB/s (but shared across all SMs). Flash Attention optimization: standard attention materializes QK^T (N×N matrix) in HBM → 2 HBM reads + 1 HBM write per element. Flash Attention tiles Q, K, V into blocks that fit in SRAM (192KB), computes attention block-by-block, never writes the full N×N matrix to HBM. Result: ~2-4x speedup from reduced HBM traffic. For custom kernels: (1) maximize data reuse in shared memory, (2) minimize HBM reads/writes, (3) use tensor cores (structured matmul accelerators) for GEMM operations. Triton language simplifies writing SRAM-aware kernels compared to raw CUDA.', tags: ['cuda-memory', 'sram', 'hbm', 'flash-attention'] },
  { id: 'ai-engineer-production-infra-l4-021', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Kubernetes', question: 'How should Kubernetes be configured for GPU-based ML workloads?', options: ['K8s GPU configuration: (1) NVIDIA GPU Operator installs drivers, device plugin, and container toolkit automatically, (2) Resource requests/limits: nvidia.com/gpu: 1 allocates one GPU exclusively, (3) Node affinity/tolerations: schedule ML pods only on GPU nodes, (4) Priority classes: inference pods get higher priority than batch training, (5) GPU sharing: MIG (Multi-Instance GPU) partitions H100 into up to 7 isolated instances for smaller models, (6) Topology-aware scheduling: place tensor-parallel pods on the same node for NVLink access. GPU monitoring via DCGM exporter + Prometheus', 'GPUs are automatically shared between all pods on a node', 'Standard Kubernetes configurations work for GPU workloads', 'Kubernetes cannot manage GPU resources'], correctAnswer: 0, explanation: 'K8s GPU setup: (1) Install: NVIDIA GPU Operator (Helm chart) → auto-deploys drivers, device plugin, DCGM. (2) Pod spec: resources: {limits: {nvidia.com/gpu: "2"}} → K8s schedules on node with 2 free GPUs. GPUs are exclusively allocated (no oversubscription by default). (3) MIG for sharing: H100 MIG profiles: 1g.10gb (7 instances), 2g.20gb (3 instances), etc. Each MIG instance is a separate GPU resource. (4) Multi-node training: use MPI Operator or PyTorchJob for distributed training with proper NCCL topology. (5) Topology: label nodes with gpu-interconnect type (NVLink, PCIe), use affinity rules to co-locate tensor-parallel pods on NVLink nodes. (6) Preemption: set PriorityClass for inference (high) and batch (low) → if GPUs are scarce, batch jobs are preempted for inference.', tags: ['kubernetes', 'gpu-operator', 'mig', 'scheduling'] },
  { id: 'ai-engineer-production-infra-l4-022', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Model Format', question: 'What are the trade-offs between SafeTensors, GGUF, and ONNX model formats?', options: ['SafeTensors: safe (no code execution), fast loading (memory-mapped), HuggingFace standard. Best for: GPU serving with PyTorch/vLLM. GGUF (formerly GGML): quantized format optimized for CPU and Apple Silicon inference, used by llama.cpp. Best for: local/edge deployment without GPUs. ONNX: framework-agnostic with ONNX Runtime for cross-platform deployment and graph optimizations. Best for: production deployment across diverse hardware (GPU, CPU, mobile). Choice depends on target runtime, hardware, and deployment environment', 'All model formats are identical', 'GGUF cannot run on GPUs', 'SafeTensors only works on NVIDIA GPUs'], correctAnswer: 0, explanation: 'SafeTensors: stores tensors as raw bytes with a JSON header (no pickle → no code execution). Memory-mapped loading: pages loaded on demand by OS. Used by: HuggingFace, vLLM, TGI. GGUF: binary format with built-in quantization metadata. Stores quantized weights (Q4_K_M, Q5_K, etc.) with dequantization info. Used by: llama.cpp (CPU/Metal/CUDA), ollama, LM Studio. Optimized for: single-file distribution, CPU inference. ONNX: computation graph + weights. Enables graph-level optimizations (operator fusion, constant folding). Used by: ONNX Runtime (supports CUDA, TensorRT, OpenVINO, CoreML). Best for: non-LLM models that need cross-platform deployment. For LLMs: SafeTensors (GPU serving) or GGUF (local/CPU). For traditional ML (BERT, ResNet): ONNX for optimized cross-platform inference.', tags: ['safetensors', 'gguf', 'onnx', 'model-format'] },
  { id: 'ai-engineer-production-infra-l4-023', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Rate Limiting', question: 'How should rate limiting be designed for ML inference APIs?', options: ['Standard API rate limiting applies without modification', 'ML rate limiting should consider: (1) token-based limits (not just request count — a 10K token request costs 100x more than a 100 token request), (2) per-model limits (expensive models have lower limits), (3) priority queues (premium tier gets priority GPU access), (4) burst handling (allow short bursts above steady-state limit), (5) cost-based throttling (cap per-user spending per hour/day). Token bucket with cost-weighted tokens provides the most accurate rate limiting: each request consumes tokens proportional to its compute cost', 'Rate limiting is unnecessary for ML APIs', 'All requests should consume the same rate limit tokens'], correctAnswer: 1, explanation: 'Token-weighted rate limiting: each API key gets a budget of "compute tokens" per minute. A request consuming 100 input tokens + 200 output tokens costs 100×w_in + 200×w_out compute tokens (where w_in and w_out are cost weights per token, differing by model). Benefits: (1) prevents single user from monopolizing GPUs with long-context requests, (2) fairly allocates resources based on actual compute cost, (3) aligns with pay-per-token pricing. Implementation: Redis-based token bucket with cost-weighted decrements. Separate limits: (a) requests per minute (prevent DoS), (b) tokens per minute (prevent compute abuse), (c) concurrent requests (prevent queue monopolization). Priority: premium tier requests dequeued before free tier. Backpressure: when queue depth exceeds threshold, new requests get 429 (Too Many Requests) with Retry-After header.', tags: ['rate-limiting', 'token-based', 'priority-queues', 'cost-weighted'] },
  { id: 'ai-engineer-production-infra-l4-024', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'CI/CD', question: 'How should CI/CD pipelines be designed for ML model deployment?', options: ['ML models do not need CI/CD pipelines', 'Standard software CI/CD works for ML without modification', 'ML CI/CD additions: (1) model artifact management (large binary files, not just code), (2) GPU-based testing stages (run inference tests on GPU runners), (3) model evaluation gate (automatic quality checks before deployment), (4) canary deployment with ML-specific metrics, (5) automatic rollback on metric degradation. Pipeline: code change → lint + unit tests → build container → load model → run evaluation suite (accuracy, latency, safety) → deploy canary → monitor → promote or rollback. Model registry stores artifacts with lineage and approval status', 'Only code changes need CI/CD, not model changes'], correctAnswer: 2, explanation: 'ML CI/CD pipeline stages: (1) Code CI: lint, type check, unit tests for preprocessing/postprocessing code. (2) Model Build: download model weights → build container with model + serving code → push to container registry. (3) Model Test: run on GPU runner: load model → run golden set (500 examples) → compare metrics to baseline → assert no regressions. (4) Integration Test: end-to-end pipeline test (API call → preprocessing → inference → postprocessing → response validation). (5) Staging Deploy: deploy to staging environment → run extended evaluation suite + load test. (6) Production Deploy: canary (5% traffic) → monitor for 1 hour → auto-promote if metrics are healthy, auto-rollback if degradation detected. Tools: GitHub Actions/GitLab CI for pipeline, MLflow/W&B for model registry, ArgoCD for K8s deployment, custom scripts for metric gates.', tags: ['cicd', 'ml-pipeline', 'canary-deployment', 'model-registry'] },
  { id: 'ai-engineer-production-infra-l4-025', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Compilation', question: 'How does torch.compile improve ML inference performance?', options: ['torch.compile captures the PyTorch computation graph and generates optimized GPU kernels via TorchInductor. Key optimizations: (1) operator fusion (matmul + bias + activation → single kernel, eliminating intermediate memory reads/writes), (2) memory planning (reuse buffers across operations), (3) Triton kernel generation (auto-tuned GPU kernels). Inference speedup: 30-100% for standard models. Caveats: first inference is slow (compilation), graph breaks (data-dependent control flow) cause fallback to eager mode, and not all operations are supported', 'torch.compile only works for training, not inference', 'torch.compile has no effect on inference', 'Compilation always produces the same performance as eager mode'], correctAnswer: 0, explanation: 'torch.compile workflow: (1) TorchDynamo captures Python bytecode → computation graph, (2) TorchInductor optimizes graph: fuse pointwise ops (layernorm + dropout + residual → one kernel), plan memory reuse, generate Triton GPU kernels or C++ CPU code. (3) First call: compile (seconds to minutes), subsequent calls: run compiled code. Inference benefits: (a) fused kernels reduce HBM traffic by 2-3x for transformer blocks, (b) reduced kernel launch overhead (fewer, larger kernels), (c) optimized memory allocation. Practical: BERT inference 50% faster, stable diffusion 40% faster with compile. Limitations: (1) dynamic shapes require recompilation (mitigated by torch.compile(dynamic=True)), (2) custom CUDA extensions may not compile, (3) graph breaks at if-statements depending on tensor values. For serving: compile once at startup, serve compiled model.', tags: ['torch-compile', 'torchinductor', 'kernel-fusion', 'optimization'] },
  { id: 'ai-engineer-production-infra-l4-026', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Inference Server', question: 'What is NVIDIA Triton Inference Server and what features make it suitable for production ML serving?', options: ['Triton only supports TensorFlow models', 'Triton provides: (1) multi-framework support (TensorFlow, PyTorch, ONNX, TensorRT, custom backends), (2) dynamic batching (accumulate requests into optimal batches automatically), (3) model ensemble pipelines (chain preprocessing → inference → postprocessing as a graph), (4) concurrent model execution (run multiple models on one GPU efficiently), (5) model management (load/unload models without restart, A/B version routing), (6) built-in metrics (Prometheus, request latency, throughput). Triton is the industry standard for serving diverse ML models behind a unified API', 'Triton cannot serve multiple models on the same GPU', 'Triton is only designed for LLM serving'], correctAnswer: 1, explanation: 'Triton architecture: (1) Model Repository (local/S3): organized as model_name/version/model_files. Triton auto-detects new versions and loads them. (2) Scheduler: receives requests, routes to appropriate model backend, applies dynamic batching. (3) Backend: executes inference using the model\'s native framework. (4) Metrics: exposes request_count, request_latency, queue_time via Prometheus endpoint. Dynamic batching: if max_batch_size=8, preferred_batch_size=[4,8], max_queue_delay=100ms: accumulate up to 8 requests or wait 100ms, whichever comes first → batch inference. For LLMs: Triton + TensorRT-LLM backend provides optimized LLM serving with in-flight batching. For traditional ML: Triton + ONNX/PyTorch backend with model ensembles (e.g., preprocessing in Python → inference in TensorRT → postprocessing in Python).', tags: ['triton', 'inference-server', 'dynamic-batching', 'multi-framework'] },
  { id: 'ai-engineer-production-infra-l4-027', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Networking', question: 'What is the impact of network configuration on ML inference latency?', options: ['REST is always faster than gRPC for ML serving', 'Network latency is always less than 1ms in cloud environments', 'Network impacts: (1) TLS handshake adds 5-20ms for new connections (use connection pooling and HTTP/2 keep-alive), (2) serialization/deserialization of large payloads (images, embeddings) adds 1-10ms (use gRPC with protobuf instead of REST with JSON for 5-10x smaller payloads), (3) DNS resolution adds 1-5ms (use DNS caching), (4) load balancer adds 1-2ms (use direct server return for minimal overhead), (5) cross-AZ traffic adds 1-3ms vs same-AZ. For p99 < 100ms SLA, every millisecond of network overhead matters', 'Network configuration has negligible impact on ML inference'], correctAnswer: 2, explanation: 'Network optimization for ML serving: (1) Protocol: gRPC with protobuf → binary serialization is 5-10x smaller than JSON, streaming support for token-by-token LLM output, HTTP/2 multiplexing. (2) Connection: maintain warm connection pools to inference backends (avoid TLS handshake per request). (3) Topology: deploy client and inference service in same AZ (0.5ms vs 2ms cross-AZ). (4) Payload: for image inputs, send as binary (not base64 in JSON — 33% larger). (5) Load balancer: AWS ALB adds ~1ms, NLB adds ~0.1ms (TCP-level, no HTTP parsing). For p99 < 50ms total: model inference might be 20ms, leaving only 30ms for network + preprocessing + postprocessing. Every optimization matters. Benchmarking: measure each component separately with distributed tracing to identify network bottlenecks.', tags: ['network-latency', 'grpc', 'connection-pooling', 'optimization'] },
  { id: 'ai-engineer-production-infra-l4-028', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Cost Analysis', question: 'How should the cost of self-hosted versus API-based LLM inference be compared?', options: ['Cost comparison framework: Self-hosted: GPU costs ($/hr × hours) + engineering time (setup, maintenance, optimization) + storage + networking + monitoring. API-based: $/token × tokens. Break-even analysis: at what request volume does self-hosted become cheaper? For a 70B model: API cost ~$5/M tokens (input). Self-hosted on 4×H100: ~$16/hr, throughput ~2000 tok/s = 7.2M tok/hr = $2.22/M tokens. Break-even: ~50K requests/day. Below that: API is cheaper due to zero engineering overhead. Above: self-hosted saves 50-70%', 'Engineering costs are negligible for self-hosted ML', 'Self-hosted is always cheaper than API-based', 'API-based inference is always cheaper than self-hosted'], correctAnswer: 0, explanation: 'Detailed comparison for LLaMA-70B inference: API (e.g., Fireworks/Together): $0.90/M input tokens, $0.90/M output tokens. At 100K requests/day, avg 500 input + 200 output tokens: daily token usage: 50M input + 20M output = $45 + $18 = $63/day = $1,890/month. Self-hosted (4×H100 on AWS, on-demand): $12.36/hr × 24 × 30 = $8,900/month. But: requires ML infra engineer (~$15K/month prorated time), monitoring setup, security, updates. Total: ~$10K+/month. Break-even: ~330K requests/day where API would cost ~$6,300/month (matching self-hosted). Below 330K: API wins. Optimization tips: reserved instances (30% savings), spot instances for non-critical workloads (60-70% savings), quantization (serve on fewer GPUs). Many companies start with API, switch to self-hosted when volume justifies the engineering investment.', tags: ['cost-comparison', 'self-hosted', 'api-based', 'break-even'] },
  { id: 'ai-engineer-production-infra-l4-029', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Testing', question: 'How should load testing be conducted for ML inference services?', options: ['Load testing only needs to verify the service starts successfully', 'ML services do not need load testing before production deployment', 'Standard HTTP load testing tools are sufficient for ML services', 'ML load testing requirements: (1) realistic request distribution (vary input lengths, use production-representative prompts), (2) measure ML-specific metrics (tokens per second, TTFT, time per output token), (3) sustained load test (GPU thermal throttling may only appear after 30+ minutes), (4) burst testing (sudden traffic spikes — does the queue handle backpressure?), (5) concurrent request testing (KV cache memory under concurrent load). Tools: Locust or k6 with custom ML request generators. Key: measure p99 latency under load, not just average'], correctAnswer: 3, explanation: 'ML load testing protocol: (1) Warmup: send 100 requests to fill caches and trigger JIT compilation. (2) Baseline: 10 RPS for 5 minutes → measure p50/p99 latency, throughput, GPU metrics. (3) Ramp: increase to 50, 100, 200 RPS in 5-minute steps → find the throughput knee (where p99 latency exceeds SLA). (4) Sustained: hold at 80% of max throughput for 30 minutes → verify no thermal throttling or memory leaks. (5) Burst: 5x normal traffic for 60 seconds → verify queue handles backpressure, no dropped requests. (6) Endurance: 24-hour test at expected production load → verify no memory leaks, GPU memory stable. Request generator: sample from production logs (realistic length distribution, diverse prompts). Report: latency distribution (not just average), throughput at each RPS level, GPU utilization curve, memory usage over time, error rate.', tags: ['load-testing', 'performance', 'latency', 'throughput'] },
  { id: 'ai-engineer-production-infra-l4-030', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Data Center', question: 'What is the power and cooling challenge for GPU-dense ML inference clusters?', options: ['Air cooling is sufficient for any GPU density', 'Power consumption is identical for GPU and CPU servers', 'GPU clusters have the same power requirements as CPU clusters', 'A single H100 consumes 700W TDP. A rack of 8×H100 servers (64 GPUs): ~50kW, far exceeding typical data center rack capacity (5-15kW). This requires: (1) liquid cooling (direct-to-chip or immersion cooling to remove 50kW+ per rack), (2) high-density power distribution, (3) GPU-aware thermal management (throttling begins at 83°C). Power Usage Effectiveness (PUE) of GPU clusters is typically 1.2-1.4, meaning 20-40% additional power for cooling. These constraints limit where GPU clusters can be deployed and affect total cost of ownership'], correctAnswer: 3, explanation: 'Power math: H100 SXM: 700W. DGX H100 (8 GPUs): 10.2kW. 4 DGX per rack: 40.8kW. Traditional rack: 5-7kW. GPU rack needs 6-8x more power. Cooling: 40.8kW → 40.8kW of heat to remove. Air cooling limit: ~25kW per rack with hot/cold aisle containment. Above that: liquid cooling required. NVIDIA recommends direct-to-chip liquid cooling for DGX H100. Immersion cooling (submerge servers in dielectric fluid): most efficient but requires specialized infrastructure. Impact on inference cost: at $0.10/kWh, a rack of 32 H100s costs: 40.8kW × 24h × 365 × $0.10 × 1.3 (PUE) = $46,500/year in electricity alone. This is ~10% of the GPU lease cost but a significant consideration for large deployments. Location matters: regions with cheap power (Oregon, Iceland, Quebec) are preferred for GPU clusters.', tags: ['power', 'cooling', 'gpu-cluster', 'pue'] },
  { id: 'ai-engineer-production-infra-l4-031', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Serverless', question: 'When is serverless GPU inference appropriate and what are its limitations?', options: ['Serverless GPU is always more expensive than dedicated instances', 'Serverless GPU (Modal, Banana, Replicate, AWS Lambda with GPU): pay per invocation, auto-scales including to zero. Appropriate when: (1) traffic is bursty/unpredictable, (2) usage is low (<1000 requests/day), (3) cold start latency is acceptable (10-60 seconds for model loading), (4) no custom infrastructure expertise available. Limitations: cold start, limited GPU selection, higher per-request cost at scale, limited control over optimization. Break-even: typically at ~5000-10000 requests/day, dedicated GPU instances become cheaper', 'Serverless GPU is always better than dedicated instances', 'Serverless GPU has zero cold start latency'], correctAnswer: 1, explanation: 'Serverless GPU cost model: ~$0.0005-0.005 per second of GPU time (varies by GPU type). For a 7B model inference taking 2 seconds: $0.001-0.01 per request. At 100 requests/day: $0.10-1.00/day. Dedicated A10G: $24/day (always on). Serverless wins at low volume. At 10K requests/day: serverless $10-100/day, dedicated $24/day. Dedicated wins at high volume. Cold start: model loading takes 10-60 seconds (depends on model size and cache). Solutions: (1) keep-warm option (minimum 1 instance always ready — adds cost), (2) model caching on serverless provider\'s storage, (3) smaller models for faster loading. Modal innovates with snapshot-based fast cold starts (~3-5 seconds for cached models). For production: use serverless for development/prototyping and low-traffic internal tools. Switch to dedicated instances when traffic justifies it.', tags: ['serverless', 'cold-start', 'auto-scaling', 'cost-model'] },
  { id: 'ai-engineer-production-infra-l4-032', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Logging', question: 'What should be logged for ML inference requests and how should logs be managed?', options: ['Standard HTTP access logs are sufficient for ML services', 'Only error responses need logging', 'ML inference requests should not be logged for privacy reasons', 'ML inference logging should capture: (1) request metadata (timestamp, user_id, model_version, request_id), (2) input characteristics (token count, language, content type), (3) model output (response, confidence scores, safety filter results), (4) performance (TTFT, total latency, GPU utilization during inference, batch size), (5) cost (tokens consumed, compute time). Sampling: log 100% of metadata + performance, sample 10-100% of full inputs/outputs (privacy-preserving). Store in: hot storage (30 days for debugging), cold storage (1 year for analysis and compliance)'], correctAnswer: 3, explanation: 'Log schema: {request_id, timestamp, user_id, model, model_version, prompt_tokens, completion_tokens, ttft_ms, total_latency_ms, gpu_util, batch_size, safety_score, finish_reason, cost_usd}. Full input/output: sampled at 10% (store in separate system for privacy). Log pipeline: structured logs (JSON) → Kafka → (1) real-time monitoring (Grafana/Datadog), (2) cold storage (S3 Parquet for analysis), (3) ML feedback loop (labeled examples for retraining). Privacy: (a) never log PII in production logs without consent, (b) hash user_id for analytics, (c) redact sensitive content in sampled inputs, (d) comply with data retention policies. Volume: 10K requests/day × 1KB metadata = 10MB/day. With sampled full content: 10K × 10% × 5KB = 5MB/day. Very manageable. At 1M requests/day: 1GB metadata + 500MB content/day — still manageable with columnar storage.', tags: ['logging', 'observability', 'privacy', 'structured-logs'] },
  { id: 'ai-engineer-production-infra-l4-033', language: 'ai-engineer', level: 'level4', category: 'Production AI Infrastructure', subcategory: 'Multi-Cloud', question: 'What are the challenges of deploying ML inference across multiple cloud providers?', options: ['All clouds have identical GPU offerings and pricing', 'Multi-cloud challenges: (1) GPU availability varies by provider (H100 scarcity, different instance types), (2) model weight transfer costs ($0.09/GB egress between clouds), (3) different container runtimes and GPU drivers require separate builds, (4) networking complexity (cross-cloud latency, VPN/peering), (5) inconsistent APIs for GPU resource management. Benefits: avoid vendor lock-in, access diverse GPU types, improve availability. Practical approach: primary cloud for main serving + secondary for overflow/DR, with model artifacts replicated to both via a multi-cloud model registry', 'Multi-cloud ML deployment has no unique challenges', 'Multi-cloud deployment is always more cost-effective than single-cloud'], correctAnswer: 1, explanation: 'Multi-cloud ML challenges in detail: (1) GPU instance naming: AWS p5 (H100) vs GCP a3 (H100) vs Azure ND H100 — different configurations, pricing, availability. (2) Container differences: AWS EKS vs GKE vs AKS — NVIDIA GPU operator works on all but configuration differs. (3) Model transfer: 70B model = 140GB. Cross-cloud transfer: 140GB × $0.09 = $12.60 per model version update. (4) Feature stores: accessing AWS Redis from GCP inference adds cross-cloud latency (50-100ms). (5) Monitoring: need to aggregate metrics across providers. Strategy: (a) use Kubernetes everywhere for portability, (b) store models in each provider\'s object storage (replicate proactively), (c) use a multi-cloud model registry (MLflow, Weights & Biases) as the source of truth, (d) abstract GPU scheduling behind a common layer. Companies like Coreweave provide GPU cloud as an alternative to big-3 providers.', tags: ['multi-cloud', 'gpu-availability', 'data-transfer', 'vendor-lock-in'] },
];

export default questions;
